import React from 'react';
import { useNavigate } from 'react-router-dom';
import BottomNav from '../components/BottomNav';

function DashboardWorker() {
  const navigate = useNavigate();
  const tasks = [
    { title: 'Desain Logo Cafe Kopi Minimalis', price: 'Rp 300k', level: 'Menengah', type: 'Solo Project', slots: '1/1', category: 'Desain' },
    { title: 'Edit Video Reels TikTok F&B', price: 'Rp 500k', level: 'Mahir', type: 'Team Project', slots: '2/5', category: 'Editing' },
    { title: 'Copywriting Landing Page Fintech', price: 'Rp 250k', level: 'Pemula', type: 'Solo Project', slots: '1/1', category: 'Tulisan' }
  ];

  return (
    <div style={{ maxWidth: '402px', margin: '0 auto', background: '#F8F9FA', minHeight: '100vh', padding: '16px 20px 80px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
        <h1 style={{ fontSize: '20px', fontWeight: 800, color: '#0D9488', cursor: 'pointer' }} onClick={() => navigate('/')}>WORKIE</h1>
        <div style={{ display: 'flex', gap: '16px', fontSize: '20px' }}>
          <span>🔔</span>
          <span style={{ cursor: 'pointer' }} onClick={() => navigate('/')}>👤</span>
        </div>
      </div>
      <h2>Halo Mitra, Cari Duit Instan!</h2>

      <div style={{ display: 'flex', gap: '10px', margin: '16px 0' }}>
        <span style={{ padding: '8px 20px', background: '#0D9488', color: 'white', borderRadius: '20px', fontSize: '14px', fontWeight: 500 }}>Desain</span>
        <span style={{ padding: '8px 20px', background: 'white', borderRadius: '20px', border: '1px solid #E2E8F0', fontSize: '14px' }}>Editing</span>
        <span style={{ padding: '8px 20px', background: 'white', borderRadius: '20px', border: '1px solid #E2E8F0', fontSize: '14px' }}>Tulisan</span>
      </div>

      <h3>Tugas Tersedia Hari Ini</h3>
      {tasks.map((task, i) => (
        <div key={i} style={{ background: 'white', padding: '16px', borderRadius: '12px', marginTop: '12px' }}>
          <div style={{ display: 'flex', gap: '8px', marginBottom: '8px' }}>
            <span style={{ padding: '2px 12px', borderRadius: '12px', fontSize: '12px', fontWeight: 600, background: '#E0F2FE', color: '#0369A1' }}>{task.category}</span>
            <span style={{ padding: '2px 12px', borderRadius: '12px', fontSize: '12px', fontWeight: 600, background: '#FEF3C7', color: '#92400E' }}>{task.level}</span>
          </div>
          <h4>{task.title}</h4>
          <p style={{ fontWeight: 700, color: '#0D9488' }}>{task.price}</p>
          <div style={{ display: 'flex', gap: '16px', fontSize: '13px', color: '#475569', margin: '8px 0' }}>
            <span>{task.type}</span>
            <span>{task.slots}</span>
          </div>
          <button onClick={() => navigate('/task-detail')} style={{ width: '100%', padding: '10px', background: '#0D9488', color: 'white', border: 'none', borderRadius: '12px', fontWeight: 600 }}>Ambil Pekerjaan (Mulai)</button>
        </div>
      ))}
      <BottomNav role="worker" />
    </div>
  );
}

export default DashboardWorker;
